SINA_SMART["embryo1-membranes"] = {"lecture":"embryo1-membranes","title":"Fetal membranes and fetal assessment","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"embryo1-membranes:e0","text":"Four membranes: amnion, umbilical vesicle, allantois, chorion.","topic":"The four fetal membranes","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-membranes:e1","text":"Amniotic fluid: ~30 mL (10 wk), 450 mL (20 wk), 800-1000 mL (37 wk).","topic":"Amnion and amniotic fluid","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-membranes:e2","text":"Fluid sources: amniotic cells, diffusion, fetal urine; removal by swallowing.","topic":"Amnion and amniotic fluid","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-membranes:e3","text":"Polyhydramnios > 2 L: GI or CNS anomalies (can't swallow).","topic":"Amnion and amniotic fluid","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-membranes:e4","text":"Oligohydramnios < 500 mL: placental insufficiency, urinary anomalies → pulmonary hypoplasia.","topic":"Amnion and amniotic fluid","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-membranes:e5","text":"Yolk sac: nutrition, germ cells (week 3), blood islands (weeks 3-6), primitive gut.","topic":"Umbilical vesicle and allantois","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-membranes:e6","text":"Allantois → urachus → median umbilical ligament.","topic":"Umbilical vesicle and allantois","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-membranes:e8","text":"CVS 10-12 weeks; amniocentesis 15-18 weeks; cordocentesis after 18 weeks.","topic":"Umbilical vesicle and allantois","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-membranes:e7","text":"Ultrasound: CRL in first trimester; BPD and head circumference 16-30 weeks.","topic":"Assessing the fetus","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-membranes:e9","text":"AFP high: neural tube and wall defects; low in maternal serum: Down syndrome.","topic":"Assessing the fetus","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"la1kx7":"a","1qdnu0e":"a","1jcaypl":"a","tt8a77":"a","jsxwb6":"a","1fbv54k":"a","1uuist1":"a","14n35t":"a","djde10":"a","ik73je":"a","8qsi89":"a","1g66gkt":"a","1ewa3d2":"a","7aosh5":"a","1nazyg0":"a"},"mapCounts":{"verified":0,"auto":15,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"embryo1-membranes:e0":{"s":0,"u":["Four membranes: amnion, umbilical vesicle, allantois, chorion.","The fetal membranes are the amnion , the umbilical vesicle (yolk sac), the allantois and the chorion ."],"dp":[]},"embryo1-membranes:e1":{"s":1,"u":["Amniotic fluid: ~30 mL (10 wk), 450 mL (20 wk), 800-1000 mL (37 wk).","Volume: about 30 mL at 10 weeks, 450 mL at 20 weeks, 800-1000 mL at 37 weeks .","The amniotic membrane = amniotic cells + extraembryonic mesoderm; it surrounds the amniotic cavity ; together they form the amniotic sac , which secretes the fluid; amnion + chorion fuse as the amniochorionic membrane ."],"dp":[]},"embryo1-membranes:e2":{"s":1,"u":["Fluid sources: amniotic cells, diffusion, fetal urine; removal by swallowing.","Fluid comes from amniotic cells, diffusion across the amniochorionic membrane and, later, fetal urine ; it circulates by fetal swallowing , absorption in the gut and airways, and return to the blood.","The amniotic membrane = amniotic cells + extraembryonic mesoderm; it surrounds the amniotic cavity ; together they form the amniotic sac , which secretes the fluid; amnion + chorion fuse as the amniochorionic membrane ."],"dp":[{"h":"Why the fetus needs to breathe liquid","t":"From about week 10 the fetus makes breathing movements that move amniotic fluid in and out of the airways. The fluid, and the lung's own secretions kept in by the larynx, keep the developing airways distended, and that stretch is a key signal for lung growth and branching. With too little fluid (oligohydramnios from renal agenesis or a long leak), the chest is also compressed by the uterus and the lungs stay small: pulmonary hypoplasia , the usual cause of death in Potter sequence. It is a neat link between the kidneys and the lungs. Source: the lecture's functions of amniotic fluid and oligohydramnios complications."}]},"embryo1-membranes:e3":{"s":1,"u":["Polyhydramnios > 2 L: GI or CNS anomalies (can't swallow).","Polyhydramnios (&gt; 2000 mL): often idiopathic, or the fetus cannot swallow (digestive or CNS anomalies, e.g. oesophageal atresia, anencephaly)."],"dp":[]},"embryo1-membranes:e4":{"s":1,"u":["Oligohydramnios < 500 mL: placental insufficiency, urinary anomalies → pulmonary hypoplasia.","Oligohydramnios (&lt; 500 mL): placental insufficiency or urinary tract anomalies (renal agenesis); complications include pulmonary hypoplasia , limb defects and cord compression."],"dp":[]},"embryo1-membranes:e5":{"s":2,"u":["Yolk sac: nutrition, germ cells (week 3), blood islands (weeks 3-6), primitive gut.","Umbilical vesicle (yolk sac): transfers nutrients in weeks 2-3; gives the primordial germ cells in week 3; forms blood islands (weeks 3-6); in week 4 part of it is incorporated as the primitive gut , which gives the trachea, bronchi, lungs and alimentary canal."],"dp":[]},"embryo1-membranes:e6":{"s":2,"u":["Allantois → urachus → median umbilical ligament.","Allantois : an outpouching from the yolk sac wall into the connecting stalk; it becomes the urachus , then the median umbilical ligament .","The umbilical cord contains the yolk sac and vitelline duct with its vessels, the connecting stalk with the allantois remnant, and the umbilical vessels in Wharton's jelly."],"dp":[]},"embryo1-membranes:e8":{"s":2,"u":["CVS 10-12 weeks; amniocentesis 15-18 weeks; cordocentesis after 18 weeks.","Umbilical vesicle (yolk sac): transfers nutrients in weeks 2-3; gives the primordial germ cells in week 3; forms blood islands (weeks 3-6); in week 4 part of it is incorporated as the primitive gut , which gives the trachea, bronchi, lungs and alimentary canal."],"dp":[]},"embryo1-membranes:e7":{"s":3,"u":["Ultrasound: CRL in first trimester; BPD and head circumference 16-30 weeks.","Fetal age is estimated from somite number, crown-rump length (first trimester), crown-heel length, weight, external features, biparietal diameter and head circumference (weeks 16-30), abdominal circumference, femur and foot length.","Ultrasound (no known harm, cheap): fetal size, multiple pregnancy, placental site, abnormalities, guiding biopsies; mid-trimester scan for malformations, twins and placenta; last-trimester scan for size, growth and position."],"dp":[]},"embryo1-membranes:e9":{"s":3,"u":["AFP high: neural tube and wall defects; low in maternal serum: Down syndrome.","AFP is high in amniotic fluid (and maternal serum) with open neural tube and abdominal wall defects, and low in maternal serum in Down syndrome.","Amniocentesis (15-18 weeks): chromosomes, neural tube defects, genetic disorders; indications: advanced maternal age, risk of genetic disorder, parental chromosomal anomaly, previous spina bifida, inborn errors of metabolism."],"dp":[]}},"meta":{"la1kx7":{"a":"recall","vg":"embryo1-membranes:e0/recall/1"},"1qdnu0e":{"a":"recall","vg":"embryo1-membranes:e1/recall/1"},"1jcaypl":{"a":"recall","vg":"embryo1-membranes:e3/recall/1"},"tt8a77":{"a":"recall","vg":"embryo1-membranes:e4/recall/1"},"jsxwb6":{"a":"recall","vg":"embryo1-membranes:e4/recall/2"},"1fbv54k":{"a":"recall","vg":"embryo1-membranes:e5/recall/1"},"1uuist1":{"a":"recall","vg":"embryo1-membranes:e6/recall/1"},"14n35t":{"a":"recall","vg":"embryo1-membranes:e7/recall/1"},"djde10":{"a":"recall","vg":"embryo1-membranes:e8/recall/1"},"ik73je":{"a":"recall","vg":"embryo1-membranes:e8/recall/1"},"8qsi89":{"a":"recall","vg":"embryo1-membranes:e9/recall/1"},"1g66gkt":{"a":"recall","vg":"embryo1-membranes:e9/recall/2"},"1ewa3d2":{"a":"recall","vg":"embryo1-membranes:e8/recall/2"},"7aosh5":{"a":"recall","vg":"embryo1-membranes:e1/recall/2"},"1nazyg0":{"a":"recall","vg":"embryo1-membranes:e0/recall/1"}},"explRev":"b96d2da38f46"};
